package com.transportplatform.tms.features.driverearnings.application;
import com.transportplatform.tms.common.exception.*; import com.transportplatform.tms.common.security.*; import com.transportplatform.tms.features.audit.application.*; import com.transportplatform.tms.features.auth.domain.RoleName; import com.transportplatform.tms.features.billing.domain.*; import com.transportplatform.tms.features.driver.domain.*; import com.transportplatform.tms.features.driverportal.application.DriverPortalAccessService; import com.transportplatform.tms.features.driverearnings.api.request.*; import com.transportplatform.tms.features.driverearnings.api.response.*; import com.transportplatform.tms.features.driverearnings.domain.*; import com.transportplatform.tms.features.ride.domain.Ride; import com.transportplatform.tms.features.settings.domain.*; import java.math.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DriverEarningsService {
 private final DriverEarningsLedgerRepository ledger; private final InvoiceLineItemRepository lines; private final TenantSettingsRepository settings; private final DriverPortalAccessService driverAccess; private final CurrentAuthenticatedUserService currentUser; private final DriverRepository drivers; private final AuditLogService audit;
 public DriverEarningsService(DriverEarningsLedgerRepository ledger, InvoiceLineItemRepository lines, TenantSettingsRepository settings, DriverPortalAccessService driverAccess, CurrentAuthenticatedUserService currentUser, DriverRepository drivers, AuditLogService audit){this.ledger=ledger;this.lines=lines;this.settings=settings;this.driverAccess=driverAccess;this.currentUser=currentUser;this.drivers=drivers;this.audit=audit;}
 @Transactional public void createForCompletedRide(Ride ride) { if(ride.getDriverId()==null || ledger.existsByRideIdAndEntryType(ride.getId(),DriverEarningsEntryType.EARNED)) return; DriverEarningsLedger entry=new DriverEarningsLedger(); entry.setTenantId(ride.getTenantId());entry.setDriverId(ride.getDriverId());entry.setRideId(ride.getId());entry.setEntryType(DriverEarningsEntryType.EARNED); String currency=settings.findById(ride.getTenantId()).map(TenantSettings::getCurrency).orElse("USD");entry.setCurrency(currency); Optional<InvoiceLineItem> line=lines.findFirstByTenantIdAndSourceReferenceIdOrderByIdDesc(ride.getTenantId(),ride.getId()); BigDecimal rate=settings.findById(ride.getTenantId()).map(TenantSettings::getDriverEarningsRate).orElse(null); BigDecimal total=line.map(value->value.getInvoice().getTotalAmount()).orElse(null); entry.setInvoiceTotal(total);entry.setEarningsRate(rate); if(rate==null || total==null){entry.setStatus(DriverEarningsStatus.PENDING_CALCULATION);entry.setReason("Awaiting payment calculation");} else {entry.setStatus(DriverEarningsStatus.EARNED);entry.setAmount(total.multiply(rate).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP));} ledger.save(entry); record(entry,"EARNINGS_CREATED","Driver earnings ledger entry created for completed ride."); }
 @Transactional(readOnly=true) public DriverEarningsSummaryResponse myEarnings(){ Driver driver=driverAccess.resolveCurrentDriver(); return summary(ledger.findAllByTenantIdAndDriverIdOrderByCreatedAtDesc(driver.getTenantId(),driver.getId())); }
 @Transactional(readOnly=true) public List<DriverEarningsEntryResponse> listAdmin(){return ledger.findAllByTenantIdOrderByCreatedAtDesc(requireAdminTenant()).stream().map(this::map).toList();}
 @Transactional public BigDecimal updateRate(DriverEarningsRateRequest request){String tenant=requireAdminTenant();TenantSettings s=settings.findById(tenant).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Tenant settings were not found."));s.setDriverEarningsRate(request.rate().setScale(2,RoundingMode.HALF_UP));settings.save(s);audit.record(new AuditLogCommand(null,tenant,"DRIVER_EARNINGS","RATE_UPDATED","TENANT_SETTINGS",tenant,"Driver earnings rate updated.",null,Map.of("rate",s.getDriverEarningsRate())));return s.getDriverEarningsRate();}
 @Transactional(readOnly=true) public BigDecimal getRate(){return settings.findById(requireAdminTenant()).map(TenantSettings::getDriverEarningsRate).orElse(null);}
 @Transactional public DriverEarningsEntryResponse adjust(DriverEarningsAdjustmentRequest request){String tenant=requireAdminTenant();if(request.amount().signum()==0) throw new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.BAD_REQUEST,"Adjustment amount cannot be zero.");drivers.findByIdAndTenantId(request.driverId(),tenant).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Driver was not found."));DriverEarningsLedger e=new DriverEarningsLedger();e.setTenantId(tenant);e.setDriverId(request.driverId());e.setEntryType(DriverEarningsEntryType.ADJUSTMENT);e.setStatus(DriverEarningsStatus.EARNED);e.setAmount(request.amount().setScale(2,RoundingMode.HALF_UP));e.setCurrency(settings.findById(tenant).map(TenantSettings::getCurrency).orElse("USD"));e.setReason(request.reason().trim());ledger.save(e);record(e,"ADJUSTMENT_CREATED","Driver earnings adjustment created.");return map(e);}
 private DriverEarningsSummaryResponse summary(List<DriverEarningsLedger> entries){BigDecimal total=entries.stream().filter(e->e.getStatus()==DriverEarningsStatus.EARNED).map(DriverEarningsLedger::getAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);long pending=entries.stream().filter(e->e.getStatus()==DriverEarningsStatus.PENDING_CALCULATION).count();String currency=entries.stream().findFirst().map(DriverEarningsLedger::getCurrency).orElse("USD");return new DriverEarningsSummaryResponse(total,BigDecimal.valueOf(pending),currency,entries.stream().map(this::map).toList());}
 private DriverEarningsEntryResponse map(DriverEarningsLedger e){return new DriverEarningsEntryResponse(e.getId(),e.getDriverId(),e.getRideId(),e.getEntryType().name(),e.getStatus().name(),e.getAmount(),e.getCurrency(),e.getInvoiceTotal(),e.getEarningsRate(),e.getReason(),e.getCreatedAt());}
 private String requireAdminTenant(){AuthenticatedUser u=currentUser.requireCurrentUser();if(u.tenantId()==null||u.getAuthorities().stream().noneMatch(a->a.getAuthority().equals(RoleName.ROLE_TENANT_ADMIN.name())))throw new ApiException(ErrorCode.FORBIDDEN,HttpStatus.FORBIDDEN,"A tenant administrator account is required.");return u.tenantId();}
 private void record(DriverEarningsLedger e,String action,String summary){audit.record(new AuditLogCommand(null,e.getTenantId(),"DRIVER_EARNINGS",action,"DRIVER_EARNINGS_LEDGER",String.valueOf(e.getId()),summary,null,map(e)));}
}
